#!/usr/bin/env python3
"""Export the prototype into one HTML file, with no network dependencies."""
from pathlib import Path
import base64
import json
import mimetypes
import re
import zipfile

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'dist'
OUT.mkdir(exist_ok=True)
version = json.loads((ROOT / 'package.json').read_text())['version']
(ROOT / 'src/data/version.js').write_text(
    '// Generated by build.py from package.json; do not edit.\n'
    + 'globalThis.OrbitVersion = ' + json.dumps(version) + ';\n'
)
html = (ROOT / 'index.html').read_text()
html = html.replace('<link rel="stylesheet" href="styles.css">', '<style>' + (ROOT / 'styles.css').read_text() + '</style>')
embedded_settlement_assets = {}
def embed_script(match):
    # Follow the HTML load order: adding a module never requires a second list.
    relative = match.group(1)
    path = (ROOT / relative).resolve()
    if not path.is_relative_to(ROOT) or not relative.startswith('src/'):
        raise ValueError(f'Unsupported script: {relative}')
    js = path.read_text().replace('</script', '<\\/script')
    return '<script>\n' + js + '\n</script>'

html = re.sub(r'<script src="([^"]+)"></script>', embed_script, html)
for asset in sorted((ROOT / 'assets').rglob('*')):
    if not asset.is_file():
        continue
    relative = asset.relative_to(ROOT).as_posix()
    mime = mimetypes.guess_type(relative)[0] or 'application/octet-stream'
    encoded = base64.b64encode(asset.read_bytes()).decode('ascii')
    data_url = f'data:{mime};base64,{encoded}'
    html = html.replace(relative, data_url)
    if asset.parent == ROOT / 'assets' / 'settlements' and asset.name.startswith(('village_', 'ville_')):
        embedded_settlement_assets[relative] = data_url
if embedded_settlement_assets:
    manifest = '<script>globalThis.OrbitEmbeddedAssets = ' + json.dumps(embedded_settlement_assets) + ';</script>'
    html = html.replace('</head>', manifest + '</head>')
destination = OUT / 'nereide-prototype.html'
destination.write_text(html)
(OUT / 'nereide-zoom-continu.html').write_text(html)
manifest = (ROOT / 'manifest.webmanifest').read_text().replace('"./index.html"', '"./nereide-zoom-continu.html"')
(OUT / 'manifest.webmanifest').write_text(manifest)
print(f'Export autonome : {destination} ({destination.stat().st_size:,} octets)')
with zipfile.ZipFile(OUT / 'nereide-sources.zip', 'w', zipfile.ZIP_DEFLATED) as archive:
    sources = ['index.html', 'styles.css', 'manifest.webmanifest', 'build.py', 'README.md', 'package.json', '.gitignore', 'AGENTS.md', 'docs/ARCHITECTURE.md', 'docs/WORLDGEN.md']
    sources += [str(path.relative_to(ROOT)) for folder in ('src', 'tests', 'docs/reference')
                for path in sorted((ROOT / folder).rglob('*'))
                if path.is_file() and path.suffix in ('.js', '.cjs', '.txt', '.pdf')]
    sources += [str(path.relative_to(ROOT)) for path in sorted((ROOT / 'assets').rglob('*')) if path.is_file()]
    for relative in sources:
        path = ROOT / relative
        if path.exists():
            archive.write(path, 'nereide/' + relative)
print(f'Sources : {OUT / "nereide-sources.zip"}')
